const $=s=>document.querySelector(s),KEY='lipstick-prototype-v1',DRAFT='lipstick-draft-v1';
const families=[['nude','裸色系','奶茶色、肉桂裸','#b48877'],['rose','豆沙色系','豆沙色、玫瑰色','#ad6e7a'],['orange','橘色系','南瓜色、珊瑚色','#c57951'],['red','红色系','番茄红、正红','#af3e42'],['plum','梅子色系','梅子色、葡萄紫','#864b69'],['brown','棕色系','红棕、摩卡、巧克力棕','#805146']];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('en-CA').replace(/\//g,'-');
function iso(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function date(s){return s?new Date(s+'T12:00:00'):null}function offset(n){let d=new Date();d.setDate(d.getDate()+n);return iso(d)}
function addMonths(s,n){if(!s||!n)return '';let d=date(s),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+Number(n));let end=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,end));return iso(d)}
function expiry(x){let explicit=x.expires_on||'',calc=addMonths(x.manufactured_on,x.shelf_life_months);return explicit||calc}
function deadline(x){let e=expiry(x),p=x.lifecycle==='opened'?addMonths(x.opened_on,x.pao_months):'';return p&&e?(p<e?p:e):(p||e)}
function days(x){let d=deadline(x);return d?Math.round((Date.UTC(...d.split('-').map((n,i)=>Number(n)-(i===1?1:0)))-Date.UTC(...iso(new Date()).split('-').map((n,i)=>Number(n)-(i===1?1:0))))/86400000):null}
function period(n){return n===null?['期限待补充','unknown']:n<0?['已到期','urgent']:n===0?['今日到期','urgent']:n<=30?['30天内到期','urgent']:n<=90?['90天内到期 · 优先安排','soon']:n<=180?['约3–6个月内到期','watch']:['期限尚充裕 · 超过180天','calm']}
const fam=k=>families.find(x=>x[0]===k),life={opened:'已开封',unopened:'未开封',unknown:'状态待补充',finished:'已用完',discarded:'已丢弃'};
function seed(){return [['rose','玫瑰绒雾','R03',22,'opened','哑光'],['rose','暮色玫瑰','R07',-8,'opened','柔雾'],['nude','燕麦拿铁','N02',218,'unopened','滋润'],['brown','微醺红棕','B05',74,'opened','丝绒'],['orange','落日珊瑚','O01',155,'opened','镜面'],['red','经典绯红','R01',0,'opened','哑光'],['plum','莓果晚风','P03',null,'unknown','滋润'],['rose','温柔豆沙','R11',280,'unopened','柔雾']].map((r,i)=>({id:'demo-'+i,display_name:r[1],brand:'ATELIER · 演示品牌',series:'唇色系列',shade_code:r[2],color_family:r[0],expires_on:r[3]===null?'':offset(r[3]),lifecycle:r[4],texture:r[5],opened_on:r[4]==='opened'?offset(-100):'',pao_months:'',manufactured_on:'',shelf_life_months:'',images:[],note:'虚构演示样本，不代表真实产品或保质期。',mock:true,created_at:Date.now()-i*1000,revision:1}))}
let items;try{let raw=localStorage.getItem(KEY);items=raw?JSON.parse(raw):seed()}catch{items=seed()}
let view='inventory',selected=null,filter={life:'',time:'',color:''},sort='expiry',filtersOpen=false,compareColor='',draft=null,task=0,aiStatus='',aiMode='success',error='',dirty=false,origin='inventory';
const active=()=>items.filter(x=>!['finished','discarded'].includes(x.lifecycle));
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));items=next;return true}catch{toast('保存失败：存储空间不足，请减少图片后重试');return false}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function confirmBox(title,desc,fn,label='确认'){const d=$('#confirm');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(desc)}</p><div class="actions"><button class="secondary" id="cancelDialog">取消</button><button class="primary" id="okDialog">${esc(label)}</button></div>`;d.showModal();$('#cancelDialog').onclick=()=>d.close();$('#okDialog').onclick=()=>{d.close();fn()}}
function visual(x,large=false){let f=fam(x.color_family),col=f?.[3]||'#c4b4ac';return `<div class="visual" style="--lip:${col};--tone:${col}18">${x.images?.length?`<img src="${x.images[0]}" alt="${esc(x.display_name)}实拍图">`:'<div class="illustration" aria-label="示意插画，非产品实拍"></div>'}</div>`}
function card(x){let n=days(x),p=period(n);return `<button class="card" onclick="showDetail('${x.id}')">${visual(x)}<div class="card-body"><div class="brandline">${esc(x.brand||'我的收藏')}</div><h3>${esc(x.display_name)} <span class="mini">${esc(x.shade_code)}</span></h3><div class="tags"><span class="tag">${fam(x.color_family)?.[1]||'待分类'}</span>${x.texture?`<span class="tag">${esc(x.texture)}</span>`:''}</div><div class="deadline ${p[1]}"><span class="dot"></span>${n===null?'期限待补充':n<0?`已超过记录期限 ${-n} 天`:n===0?'今日到期':`还剩 ${n} 天`}</div><div class="statusline">${life[x.lifecycle]} · ${p[0]}</div></div></button>`}
function shell(content){$('#app').innerHTML=`<header><button class="brand" onclick="navigate('inventory')">唇间<small>THE LIP EDIT</small></button><nav><button class="${view==='inventory'?'active':''}" onclick="navigate('inventory')">我的口红柜</button><button class="${view==='compare'?'active':''}" onclick="navigate('compare')">买前查一查</button></nav><span class="demo-label">可交互原型 · 本地保存</span></header><main>${content}</main>`}
function navAction(v){view=v;render();window.scrollTo(0,0)}function navigate(v){if(view==='form'&&dirty){confirmBox('保留这次录入？','已填写的信息会保存在本地草稿，下次录入可以继续。',()=>{saveDraft();task++;aiStatus='';navAction(v)},'保留并离开')}else navAction(v)}
function saveDraft(){if(!draft)return;try{localStorage.setItem(DRAFT,JSON.stringify(draft))}catch{toast('草稿保存失败，请减少图片')}}
function options(arr,val){return arr.map(([k,n])=>`<option value="${k}" ${val===k?'selected':''}>${n}</option>`).join('')}
function inventory(){let all=active(),rows=all.filter(x=>(!filter.life||x.lifecycle===filter.life)&&(!filter.color||(filter.color==='pending'?!x.color_family:x.color_family===filter.color))&&matchTime(days(x),filter.time));rows.sort((a,b)=>sort==='expiry'?(days(a)??1e9)-(days(b)??1e9):sort==='color'?String(a.color_family).localeCompare(String(b.color_family)):b.created_at-a.created_at);let selectedFilter=Object.values(filter).some(Boolean);shell(`<div class="heading"><div><div class="eyebrow">YOUR PERSONAL COLLECTION</div><h1>我的口红柜</h1><p class="sub">让每一抹喜欢，都被好好记得。</p></div><button class="primary" onclick="newItem()">＋ 录入口红</button></div><div class="stats"><button class="stat" onclick="resetFilter()"><div><span>当前持有</span><b>${all.length}</b> <small>支</small></div><i>▱</i></button><button class="stat" onclick="filter.life='opened';render()"><div><span>已开封</span><b>${all.filter(x=>x.lifecycle==='opened').length}</b> <small>支</small></div><i>◔</i></button><button class="stat" onclick="filter.time='30';render()"><div><span>30天内到期 · 含今日</span><b>${all.filter(x=>days(x)!==null&&days(x)>=0&&days(x)<=30).length}</b> <small>支</small></div><i>◷</i></button></div><div class="toolbar"><span class="count">${selectedFilter?'筛选结果':'全部口红'} · ${rows.length} 支</span>${selectedFilter?'<button class="text-btn" onclick="resetFilter()">清除筛选</button>':''}<button class="secondary" onclick="filtersOpen=!filtersOpen;render()">☷ 筛选${selectedFilter?' · 已选':''}</button><select aria-label="排序" onchange="sort=this.value;render()">${options([['new','最近录入'],['expiry','到期日期优先'],['color','按色系']],sort)}</select></div>${filtersOpen?`<div class="filter-panel"><label>开封状态<select onchange="filter.life=this.value;render()">${options([['','全部状态'],['opened','已开封'],['unopened','未开封'],['unknown','待补充']],filter.life)}</select></label><label>期限状态<select onchange="filter.time=this.value;render()">${options([['','全部期限'],['180+','超过180天'],['180','91–180天'],['90','31–90天'],['30','30天内到期（含今日）'],['expired','已到期'],['unknown','期限待补充']],filter.time)}</select></label><label>色系<select onchange="filter.color=this.value;render()">${options([['','全部色系'],...families.map(x=>[x[0],x[1]]),['pending','待分类']],filter.color)}</select></label></div>`:''}${rows.length?`<div class="grid">${rows.map(card).join('')}</div>`:`<div class="empty"><h2>${all.length?'没有符合条件的口红':'给喜欢的口红，一个位置'}</h2><p>${all.length?'试试调整筛选条件。':'拍下整体与底部色号，开始整理你的收藏。'}</p><button class="primary" onclick="${all.length?'resetFilter()':'newItem()'}">${all.length?'清除筛选':'录入第一支'}</button></div>`}<div class="footer-note">实拍记录你的收藏 · 期限仅作提醒，不代表品质检测</div>${demoControls()}`)}
function matchTime(n,t){return !t?true:t==='unknown'?n===null:t==='expired'?n!==null&&n<0:n===null?false:t==='30'?n>=0&&n<=30:t==='90'?n>=31&&n<=90:t==='180'?n>=91&&n<=180:n>180}
function resetFilter(){filter={life:'',time:'',color:''};render()}
function demoControls(){return `<div class="demo-controls"><span>演示品牌与插画仅用于原型 · 数据仅存于本浏览器</span><div><button onclick="confirmBox('恢复演示数据？','将替换当前库存和草稿。',()=>{if(persist(seed())){localStorage.removeItem(DRAFT);render();toast('已恢复演示数据')}})">恢复演示</button> · <button onclick="confirmBox('清空库存？','当前记录将被清除，可通过恢复演示重新体验。',()=>{if(persist([])){render();toast('已清空')}})">体验空库存</button></div></div>`}
function compare(){let a=active();let groups=compareColor?families.filter(f=>f[0]===compareColor):families;shell(`<div class="eyebrow">A LITTLE PAUSE BEFORE YOU BUY</div><h1>下一支，先看看已有的。</h1><p class="sub">这次想买什么色系？让喜欢多一点不同。</p><div class="family-tabs"><button class="family ${!compareColor?'active':''}" onclick="compareColor='';render()"><span class="swatch" style="background:linear-gradient(130deg,#c59a7e,#af6d7b,#803e4c)"></span><strong>全部色系</strong><small>${a.length} 支收藏</small></button>${families.map(f=>`<button class="family ${compareColor===f[0]?'active':''}" onclick="compareColor='${f[0]}';render()"><span class="swatch" style="--lip:${f[3]}"></span><strong>${f[1]}</strong><small>${f[2]}</small></button>`).join('')}</div>${groups.map(f=>{let r=a.filter(x=>x.color_family===f[0]);return `<div class="group-title"><h2>${f[1]}</h2><span>当前持有 ${r.length} 支</span></div><p class="hint">已开封 ${r.filter(x=>x.lifecycle==='opened').length} · 未开封 ${r.filter(x=>x.lifecycle==='unopened').length} · 状态待补充 ${r.filter(x=>x.lifecycle==='unknown').length}${r.some(x=>days(x)!==null&&days(x)<0)?` · <span class="urgent">其中 ${r.filter(x=>days(x)!==null&&days(x)<0).length} 支已到期</span>`:''}</p>${r.length?`<div class="grid">${r.map(card).join('')}</div>`:'<div class="empty" style="padding:25px">尚未记录该色系</div>'}`}).join('')}${a.some(x=>!x.color_family)?`<button class="text-btn" onclick="filter.color='pending';view='inventory';render()">还有 ${a.filter(x=>!x.color_family).length} 支待分类，去完善 →</button>`:''}<div class="footer-note">同色系不代表完全相同，最终选择由你决定。</div>`)}
function showDetail(id){origin=view==='compare'?'compare':'inventory';selected=id;view='detail';render();window.scrollTo(0,0)}
function detail(){let x=items.find(x=>x.id===selected);if(!x){navAction('inventory');return}let n=days(x),p=period(n),e=expiry(x),op=addMonths(x.opened_on,x.pao_months);shell(`<button class="back" onclick="navAction(origin)">← 返回${origin==='compare'?'买前查看':'口红柜'}</button><div class="detail-grid"><div><div class="detail-image">${visual(x,true)}</div><p class="hint">${x.images?.length?'你的实拍记录':'示意插画 · 非真实产品照片'}</p>${x.images?.length>1?`<div class="thumbs">${x.images.map((im,i)=>`<button class="thumb" onclick="setCover('${x.id}',${i})" title="设为封面"><img src="${im}" alt="照片${i+1}"></button>`).join('')}</div><p class="hint">点击缩略图设为封面</p>`:''}</div><div class="detail-content"><div class="brandline">${esc(x.brand||'我的口红')}</div><h1>${esc(x.display_name)}</h1><p class="sub">${esc(x.series)} ${esc(x.shade_code)}</p><div class="tags" style="margin-top:18px"><span class="tag">${fam(x.color_family)?.[1]||'待分类'}</span><span class="tag">${esc(x.texture||'质地未记录')}</span><span class="tag">${life[x.lifecycle]}</span></div><div class="panel"><h3>使用期限 <span class="tag ${p[1]}">${p[0]}</span></h3><div class="date-big ${p[1]}">${n===null?'—':Math.abs(n)} <small>${n===null?'期限待补充':n<0?'天前已到期':'天剩余'}</small></div>${x.opened_on&&deadline(x)?`<progress max="100" value="${Math.min(100,Math.max(0,100*(date(iso(new Date()))-date(x.opened_on))/(date(deadline(x))-date(x.opened_on))))}"></progress>`:''}<div class="rows"><div class="row"><span>开封日期</span>${x.opened_on||'未记录'}</div><div class="row"><span>提醒截止日</span>${deadline(x)||'待补充'}</div><div class="row"><span>依据</span>${op&&e?'采用开封与实物期限的较早值':op?'按开封后期限计算':e?(x.expires_on?'按实物到期日期':'按生产日期＋保质期推算'):'暂无足够信息'}</div></div><details><summary>查看日期与计算依据</summary><p>开封后使用期限：${x.pao_months?x.pao_months+'个月':'未知'}<br>开封计算截止：${op||'未知'}<br>实物标注到期：${x.expires_on||'未记录'}<br>生产日期：${x.manufactured_on||'未记录'}<br>未开封保质期：${x.shelf_life_months?x.shelf_life_months+'个月':'未知'}<br>信息来源：${x.mock?'模拟样本，不能用于真实产品判断':'用户确认／实物信息'}<br>日期仅供管理提醒，不代表实物品质检测。</p></details></div>${x.note?`<div class="panel"><h3>我的备注</h3><p class="sub">${esc(x.note)}</p></div>`:''}<div class="actions"><button class="primary" onclick="editItem('${x.id}')">编辑产品信息</button>${x.lifecycle==='unopened'?`<button class="secondary" onclick="editItem('${x.id}');draft.lifecycle='opened';renderForm()">标记开封</button>`:''}</div><div class="actions"><button class="text-btn" onclick="removeItem('${x.id}','finished')">已用完</button><button class="text-btn" onclick="removeItem('${x.id}','discarded')">移出库存</button><button class="text-btn danger" onclick="deleteItem('${x.id}')">删除记录</button></div></div></div>`)}
function setCover(id,i){let a=structuredClone(items),x=a.find(x=>x.id===id);let pic=x.images.splice(i,1)[0];x.images.unshift(pic);if(persist(a))render()}
function removeItem(id,state){confirmBox('移出这支口红？','移出后不再计入库存和同色系数量，不提供历史浏览入口。',()=>{let a=items.map(x=>x.id===id?{...x,lifecycle:state}:x);if(persist(a)){navAction(origin);toast('已移出库存')}})}function deleteItem(id){confirmBox('删除这条记录？','产品信息和本地照片将一并删除，此操作不能撤销。',()=>{if(persist(items.filter(x=>x.id!==id))){navAction(origin);toast('已删除')}} ,'删除')}
function blank(){return {id:'item-'+Date.now(),display_name:'',brand:'',series:'',shade_code:'',color_family:'',texture:'',lifecycle:'unknown',opened_on:'',pao_months:'',expires_on:'',manufactured_on:'',shelf_life_months:'',images:[],note:'',created_at:Date.now(),revision:0}}
function newItem(){let saved;try{saved=JSON.parse(localStorage.getItem(DRAFT))}catch{}draft=saved||blank();dirty=false;aiStatus='';error='';view='form';render();window.scrollTo(0,0);if(saved)toast('已恢复未完成草稿')}
function editItem(id){draft=structuredClone(items.find(x=>x.id===id));dirty=false;error='';aiStatus='';view='form';render();window.scrollTo(0,0)}
function upd(k,v){if(['brand','series','shade_code'].includes(k)&&draft[k]!==v&&draft.mock){draft.identity_changed=true;aiStatus='产品身份已修改，请核对色系与期限后保存。'}draft[k]=v;dirty=true;saveDraft()}
function field(label,key,type='text',help=''){return `<label class="field">${label}<input type="${type}" value="${esc(draft[key])}" ${type==='number'?'min="1" step="1"':''} ${['opened_on','manufactured_on'].includes(key)?`max="${iso(new Date())}"`:''} oninput="upd('${key}',this.value)" maxlength="${key==='display_name'?100:200}">${help?`<small>${help}</small>`:''}</label>`}
function renderForm(){if(!draft)return;let focused=document.activeElement;let focusKey=focused?.getAttribute('oninput');let caret=focused?.selectionStart;let scrollY=window.scrollY;let busy=['识别中','查询资料中'].includes(aiStatus);shell(`<div class="form-wrap"><button class="back" onclick="navigate('inventory')">← 返回口红柜</button><div class="form-head"><div class="eyebrow">MAKE ROOM FOR YOUR FAVORITES</div><h1>${draft.revision?'编辑口红':'录入一支喜欢'}</h1><p class="sub">上传后就能填写开封信息，识别结果稍后自动补齐。</p></div><div class="form-panel"><div class="section-label">01 / PHOTOS</div><h2>先拍下它</h2><label class="upload-zone"><input type="file" accept="image/jpeg,image/png,image/webp" multiple onchange="upload(this.files)"><span style="font-size:25px;color:#a7857c">＋</span><b>上传整体图与底部色号</b><small>有包装可补拍日期与开封后期限标记<br>最多3张 · JPG / PNG / WebP · 每张10MB以内</small></label>${draft.images.length?`<div class="thumbs">${draft.images.map((im,i)=>`<div class="thumb"><img src="${im}" alt="已上传照片${i+1}"><button aria-label="移除照片" onclick="draft.images.splice(${i},1);upd('images',draft.images);renderForm()">×</button></div>`).join('')}</div>`:''}<div class="actions"><button class="secondary" ${busy?'disabled':''} onclick="runAI()">${draft.images.length?'重新模拟识别':'体验模拟识别'}</button><select aria-label="模拟结果" onchange="aiMode=this.value">${options([['success','模拟：正常结果'],['partial','模拟：部分成功'],['fail','模拟：查询失败'],['ambiguous','模拟：身份歧义']],aiMode)}</select></div><div class="ai-box">✧ ${aiStatus||'AI 识别为模拟演示，照片不会发送到外部服务。'} ${busy?'<button class="text-btn" onclick="task++;aiStatus=\'已取消，可继续手动填写\';renderForm()">取消</button>':''}${aiStatus==='需要确认产品身份'?'<div class="actions"><button class="secondary" onclick="applyAI();aiStatus=\'已选择演示系列，结果请核对\';renderForm()">演示品牌 · 唇色系列 R03</button><button class="text-btn" onclick="aiStatus=\'请手动填写产品身份\';renderForm()">都不是，手动填写</button></div>':''}</div></div><div class="form-panel"><div class="section-label">02 / OPENING DATE</div><h2>它开封了吗？</h2><div class="seg">${['opened','unopened','unknown'].map(k=>`<button class="${draft.lifecycle===k?'active':''}" onclick="upd('lifecycle','${k}');renderForm()">${life[k]}</button>`).join('')}</div>${draft.lifecycle==='opened'?`${field('开封日期','opened_on','date','不记得具体日期可留空，不会擅自按今天计算。')}<button class="text-btn" onclick="upd('opened_on','');renderForm()">不记得开封日期</button>`:'<p class="hint">可先选择状态，之后随时在详情中修改。</p>'}</div><div class="form-panel"><div class="section-label">03 / PRODUCT DETAILS</div><h2>确认产品信息</h2>${field('名称 *','display_name') }<div class="two">${field('品牌','brand')}${field('系列','series')}${field('色号','shade_code')}<label class="field">色系 · 请确认<select onchange="upd('color_family',this.value)">${options([['','待分类'],...families.map(f=>[f[0],f[1]+' · '+f[2]])],draft.color_family)}</select><small>AI先建议，以你的选择为准。</small></label>${field('质地','texture')}</div></div><div class="form-panel"><div class="section-label">04 / DATES & NOTES</div><h2>期限信息</h2><p class="hint">开封后使用期限与未开封保质期不同；不确定可留空。</p><div class="two">${field('开封后使用期限（月）','pao_months','number')}${field('实物标注到期日','expires_on','date')}</div><details ${draft.manufactured_on?'open':''}><summary>只有生产日期？补充推算信息</summary><div class="two" style="margin-top:18px">${field('实物生产日期','manufactured_on','date')}${field('未开封保质期（月）','shelf_life_months','number')}</div></details><label class="field" style="margin-top:22px">备注<textarea rows="3" maxlength="500" oninput="upd('note',this.value)">${esc(draft.note)}</textarea></label><p class="hint">日期由你核对确认；模拟识别不会生成真实产品的保质期。</p></div>${error?`<div class="inline-error" role="alert">${esc(error)}</div>`:''}<div class="form-foot"><button class="secondary" onclick="confirmBox('放弃这次修改？','未保存的信息将被清除，已有库存不受影响。',()=>{task++;localStorage.removeItem(DRAFT);dirty=false;draft=null;navAction('inventory')},'放弃修改')">取消录入</button><button class="primary" onclick="saveItem()">确认并保存</button></div></div>`);if(focusKey){let el=[...document.querySelectorAll('[oninput]')].find(e=>e.getAttribute('oninput')===focusKey);if(el){el.focus({preventScroll:true});try{el.setSelectionRange(caret,caret)}catch{}}}window.scrollTo(0,scrollY)}
async function upload(files){let fs=[...files];if(fs.length+draft.images.length>3){toast('最多上传3张照片');return}for(let f of fs){if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024){toast('请上传10MB以内的 JPG、PNG 或 WebP');return}}let id=draft.id;for(let f of fs){let raw=await new Promise(r=>{let fr=new FileReader();fr.onload=()=>r(fr.result);fr.readAsDataURL(f)});let img=await new Promise(r=>{let i=new Image();i.onload=()=>r(i);i.src=raw});let canvas=document.createElement('canvas'),scale=Math.min(1,1000/Math.max(img.width,img.height));canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);if(draft?.id!==id)return;draft.images.push(canvas.toDataURL('image/jpeg',.8))}dirty=true;saveDraft();renderForm();runAI()}
function applyAI(){if(!draft)return;let suggestions={display_name:'玫瑰绒雾（模拟结果）',brand:'ATELIER · 演示品牌',series:'唇色系列',shade_code:'R03',color_family:'rose',texture:'哑光'};for(let [k,v]of Object.entries(suggestions)){if(!draft[k])draft[k]=v}draft.mock=true;dirty=true;saveDraft()}
function runAI(){let t=++task;aiStatus='识别中';renderForm();setTimeout(()=>{if(t!==task||view!=='form')return;aiStatus='查询资料中';renderForm()},1000);setTimeout(()=>{if(t!==task||view!=='form')return;if(aiMode==='fail')aiStatus='查询未完成，已保留输入。可重试或手动填写。';else if(aiMode==='ambiguous')aiStatus='需要确认产品身份';else{applyAI();aiStatus=aiMode==='partial'?'已识别部分信息，期限未找到可靠依据，请手动核对。':'模拟结果已补齐，请核对品牌、色号与色系。日期需自行确认。'}renderForm()},2400)}
function validate(x){if(!x.display_name.trim())return '请填写产品名称，也可以用自己的称呼。';if(x.opened_on>iso(new Date()))return '开封日期不能晚于今天。';if(x.manufactured_on>iso(new Date()))return '生产日期不能晚于今天。';for(let k of ['pao_months','shelf_life_months'])if(x[k]&&(!Number.isInteger(Number(x[k]))||Number(x[k])<=0))return '使用期限应为正整数月。';let e=expiry(x);if(x.lifecycle==='opened'&&x.opened_on&&e&&x.opened_on>e)return '开封日期晚于实物到期日，请核对或清除不确定日期。';if(x.expires_on&&x.manufactured_on&&x.shelf_life_months&&x.expires_on!==addMonths(x.manufactured_on,x.shelf_life_months))return '实物到期日与生产日期推算结果不一致，请核对并清除不确定的信息。';return ''}
function saveItem(){error=validate(draft);if(error){renderForm();setTimeout(()=>$('.inline-error')?.scrollIntoView({block:'center'}),30);return}let existing=items.find(x=>x.id===draft.id);if(existing&&existing.revision!==draft.revision){error='记录已在其他窗口修改。请保留草稿后重新打开。';renderForm();return}let x={...draft,revision:(draft.revision||0)+1};let a=existing?items.map(r=>r.id===x.id?x:r):[x,...items];if(persist(a)){task++;localStorage.removeItem(DRAFT);dirty=false;selected=x.id;origin='inventory';view='detail';render();window.scrollTo(0,0);toast('已保存到口红柜')}}
window.addEventListener('storage',e=>{if(e.key===KEY){try{items=JSON.parse(e.newValue)||[];if(view!=='form')render()}catch{}}});
function render(){({inventory,compare,detail,form:renderForm}[view]||inventory)()}
window.__test={addMonths,days,deadline,expiry,period,validate,seed};render();
